import React from 'react';
import { Link, graphql } from 'gatsby';
import {
  Article,
  Content,
  Header,
  Layout,
  SEO,
  SectionTitle,
  Subline,
  Wrapper,
} from '../components';
import config from '../../config/SiteConfig';
import Post from '../models/Post';
import { CategoryDescription } from '../models/Description';

interface Props {
  data: { allMarkdownRemark: { nodes: Post[]; totalCount: number } };
  pageContext: { categoryName: string };
}

export default function CategoryTemplate({ data, pageContext }: Props) {
  const { categoryName } = pageContext;
  const { nodes, totalCount } = data.allMarkdownRemark;

  return (
    <Layout>
      <Header>
        <Link to="/">
          <strong>{config.siteTitle}</strong>
        </Link>
        <SectionTitle>Category &ndash; {categoryName}</SectionTitle>
        <Subline>
          {totalCount}개의 글 · <Link to="/categories/">전체 카테고리</Link>
        </Subline>
      </Header>
      <Wrapper>
        <Content>
          {nodes.map((post) => (
            <Article
              title={post.frontmatter.title}
              date={post.frontmatter.date}
              excerpt={post.excerpt}
              slug={post.fields.slug}
              timeToRead={post.timeToRead}
              category={post.frontmatter.category}
              key={post.fields.slug}
            />
          ))}
        </Content>
      </Wrapper>
    </Layout>
  );
}

export const Head = ({ data, pageContext }: Props) => (
  <SEO
    pathname={`/categories/${pageContext.categoryName}/`}
    title={`${pageContext.categoryName} 글 | ${config.siteTitle}`}
    description={`${CategoryDescription[pageContext.categoryName] || `${pageContext.categoryName} 관련 글`} ${data.allMarkdownRemark.totalCount}개를 모았습니다.`}
  />
);

export const CategoryQuery = graphql`
  query CategoryPage($categoryName: String!) {
    allMarkdownRemark(
      filter: { frontmatter: { category: { eq: $categoryName }, draft: { ne: true } } }
      sort: { frontmatter: { date: DESC } }
    ) {
      totalCount
      nodes {
        id
        fields {
          slug
        }
        frontmatter {
          title
          date(formatString: "YYYY-MM-DD")
          category
        }
        excerpt(pruneLength: 200)
        timeToRead
      }
    }
  }
`;
